package main

import (
    "fmt"
    "net/url"
    "regexp"
)

func getURLForQuery(apiURL, userID string) *string {
    // Validate userID contains only allowed characters
    if !regexp.MustCompile(`^[a-zA-Z0-9_-]+$`).MatchString(userID) {
        return nil
    }

    // Sanitize the userID to prevent path traversal or injection
    sanitizedID := url.QueryEscape(userID)

    // Safely concatenate using URL package
    url, err := url.Parse(apiURL)
    if err != nil {
        return nil
    }
    url.Path += "/" + sanitizedID

    return &url.String()
}

func main() {
    apiURL := "https://example.com/api/user"
    userID := "aBc123"
    result := getURLForQuery(apiURL, userID)
    fmt.Printf("%v\n", result)  // Output: https://example.com/api/user/aBc123

    userID = ""
    result = getURLForQuery(apiURL, userID)
    fmt.Printf("%v\n", result)  // Output: <nil>

    userID = "../malicious"
    result = getURLForQuery(apiURL, userID)
    fmt.Printf("%v\n", result)  // Output: <nil>
}

