func getURLForQuery(apiURL, userID string) *string {
    if userID == "" {
        return nil
    }

    // Validate that userID contains only alphanumeric characters and underscores
    if !regexp.MustCompile(`^[a-zA-Z0-9_]+$`).MatchString(userID) {
        return nil
    }

    url := apiURL + "/" + userID
    return &url
}
